#!/bin/bash
# verify30.sh -- Isabelle builds of the 30 theories regenerated by the published generator from the
# recorded models of the 25 SRanger, LRE and Diagnosis-only Chemical Detector runs (Tables 7 and 8).
#
# Run in YOUR terminal (Docker Desktop up):   bash <dir>/verify30.sh
# Resumable; goal_timeout and environment rows (MEMKILL/UNKNOWN/DOCKERDOWN) are rebuilt on rerun.
# Higher proof cap for a rerun: V30_TIMEOUT=1800 bash <dir>/verify30.sh Paste <dir>/verify30.log back.
set -u
D="$(cd "$(dirname "$0")" && pwd)"; FORGE="${FORGE:-$HOME/Git/Forge}"
ISA="${ISA:-$FORGE/scripts/isabelle-docker.sh}"; CAP="${V30_CAP:-1800}"; PAR="${V30_PAR:-2}"
RES="$D/results.csv"; [ -f "$RES" ] || echo "run,theory,status,seconds,note" > "$RES"
log(){ echo "$*" | tee -a "$D/verify30.log" >&2; }
log "=== verify30 $(date '+%F %H:%M:%S') generator=$(git -C "$FORGE" rev-parse --short HEAD) ==="
[ "${V30_SKIP_DOCKER_CHECK:-0}" = 1 ] || docker info >/dev/null 2>&1 || { log "FATAL: Docker is not running"; exit 1; }
build_one(){  # <run> <thy>
  local run="$1" thy="$2" d="$D/isabelle/$1-$2" sess; sess="$(printf '%s' "${run}__${thy}_Check" | tr -c 'A-Za-z0-9_\n' '_')"
  grep -q "^$run,$thy,\(verified\|proof_failed\)," "$RES" && return 0
  sed -i '' "/^$run,$thy,/d" "$RES" 2>/dev/null || sed -i "/^$run,$thy,/d" "$RES"
  rm -rf "$d"; mkdir -p "$d"; cp "$D/$run/isabelle/$thy.thy" "$d/"
  printf 'session %s = "Z_Machines" +\n  theories\n    %s\n' "$sess" "$thy" > "$d/ROOT"
  local t0; t0=$(date +%s)
  ( cd "$d" && "$ISA" build -d . -o "timeout=${V30_TIMEOUT:-600}" -o "threads=4" -o quick_and_dirty=false -v "$sess" ) > "$d/build.log" 2>&1; local rc=$?
  local el=$(( $(date +%s) - t0 )) status
  if grep -q "^Finished $sess" "$d/build.log"; then status=verified
  elif grep -q "^\*\*\* Timeout" "$d/build.log"; then status=goal_timeout
  elif grep -qE "Failed to finish proof|\*\*\* " "$d/build.log"; then status=proof_failed
  elif [ $rc -eq 137 ] || grep -qi "killed" "$d/build.log"; then status=MEMKILL
  elif ! docker info >/dev/null 2>&1 && [ "${V30_SKIP_DOCKER_CHECK:-0}" != 1 ]; then status=DOCKERDOWN
  else status=UNKNOWN; fi
  echo "$run,$thy,$status,$el,rc=$rc timeout=${V30_TIMEOUT:-600}" >> "$RES"; log "  $run/$thy: $status (${el}s)"
}
export -f build_one log; export D ISA RES CAP
# Movement theories one at a time, the rest PAR at a time
jobs_small=(); jobs_mv=()
while IFS=$'\t' read -r run rel; do for t in "$D/$run"/isabelle/*_Beh.thy; do thy=$(basename "$t" .thy)
  case "$thy" in Movement*) jobs_mv+=("$run $thy");; *) jobs_small+=("$run $thy");; esac; done; done < "$D/runs.tsv"
printf '%s\n' "${jobs_small[@]}" | xargs -P "$PAR" -L 1 bash -c 'build_one $0 $1'
printf '%s\n' "${jobs_mv[@]}"    | xargs -P 1      -L 1 bash -c 'build_one $0 $1'
log "done: $(grep -c ',verified,' "$RES") verified, $(grep -c ',proof_failed,' "$RES") failed, $(grep -c ',goal_timeout,' "$RES") goal timeouts, $(grep -cE ',(MEMKILL|UNKNOWN|DOCKERDOWN),' "$RES") environment rows"
log "=== DONE $(date '+%F %H:%M:%S') ==="; log "  Paste $D/verify30.log back."
